const DAYS = ['Monday','Tuesday','Wednesday','Thursday','Friday'];
const MONTHS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const cohortLabel = c => 'Cohort ' + c;

const fmt = str => { if(!str)return''; const d=new Date(str+'T12:00:00'); return MONTHS[d.getMonth()]+' '+d.getDate(); };
const fmtFull = str => { if(!str)return''; return new Date(str+'T12:00:00').toLocaleDateString('en-US',{month:'long',day:'numeric',year:'numeric'}); };

function getWeekDates(dateStr) {
  const d=new Date(dateStr+'T12:00:00'),day=d.getDay(),mon=new Date(d);
  mon.setDate(d.getDate()-(day===0?6:day-1));
  return Array.from({length:5},(_,i)=>{ const dd=new Date(mon); dd.setDate(mon.getDate()+i); return dd.toISOString().split('T')[0]; });
}
function getAllWeeks(keys) {
  const weeks=[],seen=new Set();
  for(const d of [...keys].sort()){ const wd=getWeekDates(d); if(!seen.has(wd[0])){ seen.add(wd[0]); weeks.push({key:wd[0],dates:wd,label:fmt(wd[0])+' – '+fmt(wd[4])}); } }
  return weeks;
}
function getWkDay(cohort,date){ return WK_LOOKUP[cohort+'|'+date]||null; }
// Get color for a cohort on a given date — based on current course
function getCourseColor(cohort,date){ const info=WK_LOOKUP[cohort+'|'+date]; return info?COURSE_COLORS[info.m]||'#888':'#888'; }

