function CohortManagerModal({cohortInfo,schedData,onUpdate,onDelete,onClose}) {
  const [info,setInfo] = useState(JSON.parse(JSON.stringify(cohortInfo)));
  const [confirmDelete,setConfirmDelete] = useState(null);

  const updateField=(id,field,val)=>setInfo(p=>({...p,[id]:{...p[id],[field]:val}}));

  return (
    <div onClick={onClose} style={{position:'fixed',inset:0,background:'rgba(0,0,0,0.4)',display:'flex',
      alignItems:'center',justifyContent:'center',zIndex:1000,padding:16}}>
      <div onClick={e=>e.stopPropagation()} style={{background:'#fff',borderRadius:14,padding:'22px 26px',
        width:'100%',maxWidth:560,maxHeight:'85vh',overflowY:'auto',
        boxShadow:'0 20px 60px rgba(0,0,0,0.2)',fontFamily:'system-ui,sans-serif'}}>
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:18}}>
          <div style={{fontSize:17,fontWeight:700,color:'#1a1a2e'}}>Manage Cohorts</div>
          <button onClick={onClose} style={{background:'none',border:'none',fontSize:18,cursor:'pointer',color:'#9ca3af'}}>✕</button>
        </div>

        {/* Import banner */}
        <div style={{background:'#f0f9ff',border:'1px solid #bae6fd',borderRadius:8,padding:'10px 14px',marginBottom:16}}>
          <div style={{fontSize:12,fontWeight:600,color:'#0369a1',marginBottom:4}}>Import from file</div>
          <div style={{fontSize:11,color:'#0369a1',marginBottom:8}}>
            Upload a CSV with columns: cohort, slot (d/e), start (YYYY-MM-DD), end (YYYY-MM-DD)
          </div>
          <ImportButton onImport={imported=>{
            setInfo(p=>({...p,...imported}));
          }}/>
        </div>

        <div style={{display:'flex',flexDirection:'column',gap:8}}>
          {Object.entries(info).map(([id,cohort])=>{
            const color = (() => {
              // Find the most recent date for this cohort to get current course color
              const dates = Object.keys(schedData).filter(d=>schedData[d].as.some(a=>a.c===id)).sort();
              const last = dates[dates.length-1];
              return last ? getCourseColor(id,last) : '#888';
            })();
            return (
              <div key={id} style={{border:'1px solid #f0f0f0',borderRadius:8,padding:'10px 12px',
                display:'flex',gap:10,alignItems:'center',flexWrap:'wrap'}}>
                <div style={{width:10,height:10,borderRadius:3,background:color,flexShrink:0}}/>
                <div style={{fontWeight:600,fontSize:13,minWidth:60,color:'#1a1a2e'}}>Cohort {id}</div>
                <select value={cohort.slot} onChange={e=>updateField(id,'slot',e.target.value)}
                  style={{padding:'4px 8px',borderRadius:6,border:'1px solid #ddd',fontSize:12,background:'#fff'}}>
                  <option value="d">Day</option>
                  <option value="e">Evening</option>
                </select>
                <div style={{display:'flex',alignItems:'center',gap:4}}>
                  <span style={{fontSize:11,color:'#9ca3af'}}>Start</span>
                  <input type="date" value={cohort.start} onChange={e=>updateField(id,'start',e.target.value)}
                    style={{padding:'4px 6px',borderRadius:6,border:'1px solid #ddd',fontSize:12}}/>
                </div>
                <div style={{display:'flex',alignItems:'center',gap:4}}>
                  <span style={{fontSize:11,color:'#9ca3af'}}>End</span>
                  <input type="date" value={cohort.end} onChange={e=>updateField(id,'end',e.target.value)}
                    style={{padding:'4px 6px',borderRadius:6,border:'1px solid #ddd',fontSize:12}}/>
                </div>
                {confirmDelete===id ? (
                  <div style={{display:'flex',gap:4,marginLeft:'auto'}}>
                    <span style={{fontSize:11,color:'#b91c1c',alignSelf:'center'}}>Remove?</span>
                    <button onClick={()=>{onDelete(id);setConfirmDelete(null);}}
                      style={{padding:'3px 10px',borderRadius:6,border:'none',background:'#b91c1c',
                        color:'#fff',fontSize:11,cursor:'pointer',fontWeight:600}}>Yes</button>
                    <button onClick={()=>setConfirmDelete(null)}
                      style={{padding:'3px 10px',borderRadius:6,border:'1px solid #ddd',
                        background:'#f5f5f5',fontSize:11,cursor:'pointer'}}>No</button>
                  </div>
                ) : (
                  <button onClick={()=>setConfirmDelete(id)}
                    style={{marginLeft:'auto',padding:'3px 10px',borderRadius:6,border:'1px solid #fca5a5',
                      background:'#fef2f2',color:'#b91c1c',fontSize:11,cursor:'pointer'}}>Remove</button>
                )}
              </div>
            );
          })}
        </div>

        <div style={{display:'flex',justifyContent:'flex-end',gap:8,marginTop:18}}>
          <button onClick={onClose} style={{padding:'8px 18px',borderRadius:8,border:'1px solid #ddd',background:'#f5f5f5',fontSize:13,cursor:'pointer',color:'#444'}}>Cancel</button>
          <button onClick={()=>onUpdate(info)}
            style={{padding:'8px 18px',borderRadius:8,border:'none',background:'#1a1a2e',color:'#fff',fontSize:13,cursor:'pointer',fontWeight:600}}>Save changes</button>
        </div>
      </div>
    </div>
  );
}

// ─── CSV Import Button ────────────────────────────────────────────────────────
function ImportButton({onImport}) {
  const ref = useRef();
  const handleFile = e => {
    const file = e.target.files[0];
    if(!file) return;
    const reader = new FileReader();
    reader.onload = ev => {
      try {
        const lines = ev.target.result.split('\n').filter(l=>l.trim());
        const result = {};
        // Skip header row if present
        const start = lines[0].toLowerCase().includes('cohort') ? 1 : 0;
        for(let i=start;i<lines.length;i++) {
          const [cohort,slot,startDate,endDate] = lines[i].split(',').map(s=>s.trim());
          if(cohort && slot && startDate && endDate) {
            result[cohort] = {slot: slot.toLowerCase(), start: startDate, end: endDate};
          }
        }
        if(Object.keys(result).length > 0) onImport(result);
        else alert('No valid rows found. Expected: cohort, slot, start (YYYY-MM-DD), end (YYYY-MM-DD)');
      } catch(err) { alert('Error reading file: '+err.message); }
    };
    reader.readAsText(file);
    e.target.value = '';
  };
  return (
    <>
      <input ref={ref} type="file" accept=".csv,.txt" onChange={handleFile} style={{display:'none'}}/>
      <button onClick={()=>ref.current.click()}
        style={{padding:'5px 14px',borderRadius:7,border:'1px solid #bae6fd',background:'#e0f2fe',
          color:'#0369a1',fontSize:12,cursor:'pointer',fontWeight:500}}>
        Upload CSV
      </button>
    </>
  );
}

// ─── Edit Modal ───────────────────────────────────────────────────────────────
function EditModal({dateStr,assignmentIdx,data,onSave,onClose}) {
  const day=data[dateStr], a=day?.as[assignmentIdx];
  if(!a) return null;
  const wkInfo=getWkDay(a.c,dateStr);
  const color=getCourseColor(a.c,dateStr);
  const [instructors,setInstructors]=useState(a.i||[]);
  const [subs,setSubs]=useState(a.sb||[]);
  const [available,setAvailable]=useState(day.av||[]);
  const [showSubs,setShowSubs]=useState((a.sb||[]).length>0);
  const toggle=(list,set,name)=>set(p=>p.includes(name)?p.filter(n=>n!==name):[...p,name]);
  return (
    <div onClick={onClose} style={{position:'fixed',inset:0,background:'rgba(0,0,0,0.4)',display:'flex',
      alignItems:'center',justifyContent:'center',zIndex:1000,padding:16}}>
      <div onClick={e=>e.stopPropagation()} style={{background:'#fff',borderRadius:14,padding:'22px 26px',
        width:'100%',maxWidth:440,maxHeight:'85vh',overflowY:'auto',
        boxShadow:'0 20px 60px rgba(0,0,0,0.2)',fontFamily:'system-ui,sans-serif'}}>
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',marginBottom:16}}>
          <div>
            <div style={{fontSize:11,color:'#9ca3af',marginBottom:4}}>{fmtFull(dateStr)}</div>
            <div style={{display:'flex',alignItems:'center',gap:6,flexWrap:'wrap',marginBottom:6}}>
              <span style={{padding:'2px 9px',borderRadius:6,fontSize:12,fontWeight:700,
                background:color+'18',color,border:'1px solid '+color+'44'}}>
                Cohort {a.c}
                {wkInfo&&<span style={{opacity:.65,fontWeight:400,fontSize:10}}> W{wkInfo.w}D{wkInfo.d}</span>}
              </span>
            </div>
            <div style={{fontSize:13,fontWeight:600,color:'#1a1a2e'}}>{a.m} · {COURSES[a.m]}</div>
            <div style={{fontSize:11,color:'#888',marginTop:1}}>{a.s==='d'?'Day · 9am–2pm':'Evening · 6pm–11pm'}</div>
          </div>
          <button onClick={onClose} style={{background:'none',border:'none',fontSize:18,cursor:'pointer',color:'#9ca3af'}}>✕</button>
        </div>
        <div style={{marginBottom:14}}>
          <div style={{fontSize:12,fontWeight:700,color:'#374151',marginBottom:8}}>Lead Instructor(s)</div>
          <div style={{display:'flex',flexWrap:'wrap',gap:5}}>
            {ALL_INSTRUCTORS.map(name=>{
              const sel=instructors.includes(name);
              return <button key={name} onClick={()=>toggle(instructors,setInstructors,name)}
                style={{padding:'5px 12px',borderRadius:99,fontSize:12,cursor:'pointer',fontWeight:500,
                  background:sel?'#1a1a2e':'#f3f4f6',color:sel?'#fff':'#374151',
                  border:'1px solid '+(sel?'#1a1a2e':'#e5e7eb')}}>{sel?'✓ ':''}{name}</button>;
            })}
          </div>
        </div>
        <div style={{marginBottom:14}}>
          <button onClick={()=>setShowSubs(s=>!s)} style={{background:'none',border:'none',cursor:'pointer',
            fontSize:12,color:'#7c3aed',padding:0,fontWeight:500,display:'flex',alignItems:'center',gap:4}}>
            {showSubs?'▾':'▸'} Substitute{subs.length>0?` (${subs.length})`:''}
          </button>
          {showSubs&&<div style={{display:'flex',flexWrap:'wrap',gap:5,marginTop:8}}>
            {ALL_INSTRUCTORS.map(name=>{
              const sel=subs.includes(name);
              return <button key={name} onClick={()=>toggle(subs,setSubs,name)}
                style={{padding:'5px 12px',borderRadius:99,fontSize:12,cursor:'pointer',fontWeight:500,
                  background:sel?'#7c3aed':'#f3f4f6',color:sel?'#fff':'#374151',
                  border:'1px solid '+(sel?'#7c3aed':'#e5e7eb')}}>{sel?'✓ ':''}{name}</button>;
            })}
          </div>}
        </div>
        <div style={{marginBottom:18}}>
          <div style={{fontSize:12,fontWeight:700,color:'#374151',marginBottom:8}}>On duty this day</div>
          <div style={{display:'flex',flexWrap:'wrap',gap:5}}>
            {ALL_INSTRUCTORS.map(name=>{
              const on=available.includes(name);
              return <button key={name} onClick={()=>toggle(available,setAvailable,name)}
                style={{padding:'5px 12px',borderRadius:99,fontSize:12,cursor:'pointer',fontWeight:500,
                  background:on?'#f0fdf4':'#f9fafb',color:on?'#15803d':'#9ca3af',
                  border:'1px solid '+(on?'#86efac':'#e5e7eb')}}>{on?'✓ ':''}{name}</button>;
            })}
          </div>
        </div>
        <div style={{display:'flex',justifyContent:'flex-end',gap:8}}>
          <button onClick={onClose} style={{padding:'8px 18px',borderRadius:8,border:'1px solid #ddd',background:'#f5f5f5',fontSize:13,cursor:'pointer',color:'#444'}}>Cancel</button>
          <button onClick={()=>onSave(dateStr,assignmentIdx,{i:instructors,sb:subs,av:available})}
            style={{padding:'8px 18px',borderRadius:8,border:'none',background:'#1a1a2e',color:'#fff',fontSize:13,cursor:'pointer',fontWeight:600}}>Save</button>
        </div>
      </div>
    </div>
  );
}

// ─── Day Detail Modal ─────────────────────────────────────────────────────────
function DayModal({dateStr,data,cohortInfo,onEdit,onClose}) {
  const day=data[dateStr]; if(!day) return null;
  const {av,as}=day;
  const teachingSet=new Set(as.flatMap(a=>[...(a.i||[]),...(a.sb||[])]));
  const free=av.filter(n=>!teachingSet.has(n));
  const dayLabel=new Date(dateStr+'T12:00:00').toLocaleDateString('en-US',{weekday:'long'});
  return (
    <div onClick={onClose} style={{position:'fixed',inset:0,background:'rgba(0,0,0,0.4)',display:'flex',
      alignItems:'center',justifyContent:'center',zIndex:1000,padding:16}}>
      <div onClick={e=>e.stopPropagation()} style={{background:'#fff',borderRadius:16,padding:'22px 26px',
        width:'100%',maxWidth:520,maxHeight:'85vh',overflowY:'auto',
        boxShadow:'0 20px 60px rgba(0,0,0,0.2)',fontFamily:'system-ui,sans-serif'}}>
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',marginBottom:18}}>
          <div>
            <div style={{fontSize:12,color:'#9ca3af',marginBottom:2}}>{dayLabel}</div>
            <div style={{fontSize:20,fontWeight:700,color:'#1a1a2e'}}>{fmtFull(dateStr)}</div>
          </div>
          <button onClick={onClose} style={{background:'none',border:'none',fontSize:20,cursor:'pointer',color:'#9ca3af'}}>✕</button>
        </div>
        {free.length>0&&(
          <div style={{background:'#f0fdf4',border:'1px solid #86efac',borderRadius:8,
            padding:'8px 12px',marginBottom:14,display:'flex',alignItems:'center',gap:8,flexWrap:'wrap'}}>
            <span style={{fontSize:12,fontWeight:600,color:'#15803d',whiteSpace:'nowrap'}}>Free to cover:</span>
            {free.map(n=><span key={n} style={{fontSize:12,padding:'1px 8px',borderRadius:99,background:'#dcfce7',color:'#15803d',fontWeight:500}}>{n}</span>)}
          </div>
        )}
        {['d','e'].map(slot=>{
          const slotAs=as.filter(a=>a.s===slot && cohortInfo[a.c]);
          if(!slotAs.length) return null;
          return (
            <div key={slot} style={{marginBottom:14}}>
              <div style={{fontSize:12,fontWeight:600,color:'#6b7280',marginBottom:6,textTransform:'uppercase',letterSpacing:.5}}>
                {slot==='d'?'Day · 9:00 AM – 2:00 PM':'Evening · 6:00 PM – 11:00 PM'}
              </div>
              {slotAs.map((a,idx)=>{
                const color=getCourseColor(a.c,dateStr);
                const wkInfo=getWkDay(a.c,dateStr);
                const globalIdx=as.indexOf(a);
                return (
                  <div key={idx} style={{border:'1px solid '+color+'33',borderLeft:'3px solid '+color,
                    borderRadius:8,padding:'10px 12px',marginBottom:6,
                    display:'flex',alignItems:'flex-start',justifyContent:'space-between',gap:8}}>
                    <div style={{flex:1}}>
                      <div style={{display:'flex',alignItems:'center',gap:6,flexWrap:'wrap',marginBottom:4}}>
                        <span style={{fontSize:12,fontWeight:700,color}}>{cohortLabel(a.c)}</span>
                        {wkInfo&&<span style={{fontSize:11,color:'#9ca3af'}}>W{wkInfo.w}D{wkInfo.d}</span>}
                      </div>
                      <div style={{fontSize:12,fontWeight:600,color:'#1a1a2e',marginBottom:4}}>
                        {a.m} · {COURSES[a.m]}
                      </div>
                      <div style={{display:'flex',flexWrap:'wrap',gap:4}}>
                        {(a.i||[]).map(n=><span key={n} style={{fontSize:11,padding:'1px 8px',borderRadius:99,background:'#f3f4f6',color:'#374151',fontWeight:500}}>{n}</span>)}
                        {(a.sb||[]).map(n=><span key={n} style={{fontSize:11,padding:'1px 8px',borderRadius:99,background:'#f5f3ff',color:'#7c3aed',fontStyle:'italic'}}>{n} (sub)</span>)}
                        {!(a.i||[]).length&&!(a.sb||[]).length&&<span style={{fontSize:11,color:'#d1d5db'}}>Not assigned</span>}
                      </div>
                    </div>
                    <button onClick={()=>onEdit(dateStr,globalIdx)}
                      style={{padding:'3px 10px',borderRadius:6,border:'1px solid #e5e7eb',
                        background:'#f9fafb',fontSize:11,cursor:'pointer',color:'#6b7280',whiteSpace:'nowrap',flexShrink:0}}>Edit</button>
                  </div>
                );
              })}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Cohort Detail Modal ──────────────────────────────────────────────────────
function CohortDetail({cohortId,data,onClose}) {
  const info=WK_LOOKUP;
  const entries=[];
  for(const [date,day] of Object.entries(data).sort()){
    const a=day.as.find(x=>x.c===cohortId);
    if(a) entries.push({date,module:a.m,slot:a.s,instructors:a.i||[],subs:a.sb||[]});
  }
  const byModule={};
  for(const e of entries){ if(!byModule[e.module]) byModule[e.module]=[]; byModule[e.module].push(e); }
  const modules=Object.keys(byModule).sort((a,b)=>Number(a)-Number(b));
  const headerColor=entries.length?getCourseColor(cohortId,entries[entries.length-1].date):'#888';
  return (
    <div onClick={onClose} style={{position:'fixed',inset:0,background:'rgba(0,0,0,0.4)',display:'flex',
      alignItems:'center',justifyContent:'center',zIndex:1000,padding:16}}>
      <div onClick={e=>e.stopPropagation()} style={{background:'#fff',borderRadius:16,padding:'22px 26px',
        width:'100%',maxWidth:580,maxHeight:'85vh',overflowY:'auto',
        boxShadow:'0 20px 60px rgba(0,0,0,0.2)',fontFamily:'system-ui,sans-serif'}}>
        <div style={{display:'flex',justifyContent:'space-between',alignItems:'flex-start',marginBottom:6}}>
          <div>
            <div style={{fontSize:22,fontWeight:700,color:'#1a1a2e',marginBottom:3}}>Cohort {cohortId}</div>
            <div style={{fontSize:13,color:'#888'}}>{entries.length} class days · {modules.length} courses</div>
          </div>
          <button onClick={onClose} style={{background:'none',border:'none',fontSize:20,cursor:'pointer',color:'#9ca3af'}}>✕</button>
        </div>
        <div style={{height:2,background:'#f0f0f0',borderRadius:99,margin:'14px 0 18px'}}/>
        {modules.map(mod=>{
          const days=byModule[mod];
          const modColor=COURSE_COLORS[mod]||'#888';
          const weeks=Math.ceil(days.length/5);
          const instSet=[...new Set(days.flatMap(d=>d.instructors))];
          const subSet=[...new Set(days.flatMap(d=>d.subs))];
          return (
            <div key={mod} style={{marginBottom:12,borderRadius:10,border:'1px solid '+modColor+'33',overflow:'hidden'}}>
              <div style={{background:modColor+'0e',borderBottom:'1px solid '+modColor+'22',
                padding:'10px 14px',display:'flex',alignItems:'flex-start',justifyContent:'space-between',gap:8}}>
                <div>
                  <div style={{display:'flex',alignItems:'center',gap:8,marginBottom:3}}>
                    <span style={{fontSize:14,fontWeight:700,color:modColor}}>{mod}</span>
                    <span style={{fontSize:13,color:'#374151'}}>{COURSES[mod]}</span>
                  </div>
                  <div style={{fontSize:11,color:'#9ca3af'}}>{fmt(days[0].date)} – {fmt(days[days.length-1].date)} · {days.length} days ({weeks} wk{weeks!==1?'s':''})</div>
                </div>
                <div style={{display:'flex',flexDirection:'column',alignItems:'flex-end',gap:3}}>
                  {instSet.map(n=><span key={n} style={{fontSize:11,padding:'1px 8px',borderRadius:99,background:'#f3f4f6',color:'#374151',fontWeight:500,whiteSpace:'nowrap'}}>{n}</span>)}
                  {subSet.map(n=><span key={n} style={{fontSize:11,padding:'1px 8px',borderRadius:99,background:'#f5f3ff',color:'#7c3aed',whiteSpace:'nowrap'}}>{n} (sub)</span>)}
                </div>
              </div>
              <div style={{padding:'10px 14px'}}>
                <div style={{display:'flex',flexWrap:'wrap',gap:3}}>
                  {days.map((d,i)=>{
                    const wk=getWkDay(cohortId,d.date);
                    const hasSub=d.subs.length>0, noInst=!d.instructors.length&&!d.subs.length;
                    return (
                      <span key={i} title={fmtFull(d.date)+(hasSub?' · Sub: '+d.subs.join(', '):'')}
                        style={{fontSize:10,padding:'2px 6px',borderRadius:4,cursor:'default',fontWeight:hasSub?600:400,
                          background:noInst?'#fef9c3':hasSub?'#f5f3ff':modColor+'14',
                          color:noInst?'#92400e':hasSub?'#7c3aed':modColor,
                          border:'1px solid '+(noInst?'#fcd34d':hasSub?'#c4b5fd':modColor+'44')}}>
                        {wk?`W${wk.w}D${wk.d}`:fmt(d.date)}
                      </span>
                    );
                  })}
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── Main App ─────────────────────────────────────────────────────────────────
export default function App() {
  const [schedData,setSchedData]=useState(RAW_DATA);
  const [cohortInfo,setCohortInfo]=useState(INIT_COHORT_INFO);
  const allWeeks=useMemo(()=>getAllWeeks(Object.keys(schedData)),[schedData]);

  const [weekIdx,setWeekIdx]=useState(()=>{
    const wks=getAllWeeks(Object.keys(RAW_DATA));
    const idx=wks.findIndex(w=>w.dates.includes('2026-05-18'));
    return idx>=0?idx:0;
  });
  const [tab,setTab]=useState('week');
  const [filterInstructor,setFilterInstructor]=useState('');
  const [filterSlot,setFilterSlot]=useState('');
  const [selectedDay,setSelectedDay]=useState(null);
  const [editTarget,setEditTarget]=useState(null);
  const [selectedCohort,setSelectedCohort]=useState(null);
  const [showCohortManager,setShowCohortManager]=useState(false);

  const currentWeek=allWeeks[weekIdx];
  const weekDates=currentWeek?.dates||[];

  const handleSaveEdit=(dateStr,assignmentIdx,updates)=>{
    setSchedData(prev=>{ const next=JSON.parse(JSON.stringify(prev)); next[dateStr].as[assignmentIdx].i=updates.i; next[dateStr].as[assignmentIdx].sb=updates.sb; next[dateStr].av=updates.av; return next; });
    setEditTarget(null); setSelectedDay(dateStr);
  };
  const handleOpenEdit=(dateStr,assignmentIdx)=>{ setSelectedDay(null); setEditTarget({dateStr,assignmentIdx}); };

  const handleDeleteCohort=id=>{
    setCohortInfo(p=>{ const n={...p}; delete n[id]; return n; });
    setSchedData(prev=>{
      const next=JSON.parse(JSON.stringify(prev));
      Object.keys(next).forEach(date=>{ next[date].as=next[date].as.filter(a=>a.c!==id); });
      return next;
    });
  };

  const tabStyle=active=>({padding:'7px 18px',borderRadius:8,fontSize:13,cursor:'pointer',
    fontWeight:active?600:400,background:active?'#1a1a2e':'transparent',color:active?'#fff':'#555',border:'none'});

  const weekMonthLabel=currentWeek?new Date(currentWeek.dates[0]+'T12:00:00')
    .toLocaleDateString('en-US',{month:'long',year:'numeric'}):'';

  const NavBar=()=>(
    <div style={{display:'flex',gap:8,alignItems:'center',marginBottom:12,flexWrap:'wrap'}}>
      <button onClick={()=>setWeekIdx(i=>Math.max(0,i-1))} disabled={weekIdx===0}
        style={{padding:'5px 12px',borderRadius:7,border:'1px solid #ddd',background:'#fff',cursor:weekIdx===0?'default':'pointer',fontSize:13,color:weekIdx===0?'#ccc':'#333'}}>←</button>
      <div style={{fontSize:13,fontWeight:500,minWidth:155,textAlign:'center'}}>
        {weekMonthLabel}<br/><span style={{fontSize:11,color:'#888',fontWeight:400}}>{currentWeek?.label}</span>
      </div>
      <button onClick={()=>setWeekIdx(i=>Math.min(allWeeks.length-1,i+1))} disabled={weekIdx===allWeeks.length-1}
        style={{padding:'5px 12px',borderRadius:7,border:'1px solid #ddd',background:'#fff',cursor:weekIdx===allWeeks.length-1?'default':'pointer',fontSize:13,color:weekIdx===allWeeks.length-1?'#ccc':'#333'}}>→</button>
    </div>
  );

  return (
    <div style={{fontFamily:'system-ui,sans-serif',color:'#1a1a2e',padding:'16px',maxWidth:960,margin:'0 auto'}}>
      <div style={{marginBottom:14}}>
        <div style={{fontSize:20,fontWeight:700,letterSpacing:-0.5}}>Instructor Map — 2026</div>
        <div style={{fontSize:12,color:'#888',marginTop:2}}>12 instructors · {Object.keys(cohortInfo).length} cohorts · Click any day to view and edit</div>
      </div>

      <div style={{display:'flex',alignItems:'center',gap:8,marginBottom:16,flexWrap:'wrap'}}>
        <div style={{display:'flex',gap:4,background:'#f1f1f1',borderRadius:10,padding:4}}>
          {[['week','Week View'],['team','Team Overview'],['cohorts','Cohorts']].map(([id,label])=>(
            <button key={id} onClick={()=>setTab(id)} style={tabStyle(tab===id)}>{label}</button>
          ))}
        </div>
        <div style={{flex:1}}/>
        <button onClick={()=>setShowCohortManager(true)}
          style={{padding:'6px 14px',borderRadius:8,border:'1px solid #ddd',background:'#fff',
            fontSize:12,cursor:'pointer',color:'#555'}}>
          Manage cohorts
        </button>
      </div>

      {/* ── WEEK VIEW ── */}
      {tab==='week'&&(
        <>
          <div style={{display:'flex',gap:8,alignItems:'center',marginBottom:10,flexWrap:'wrap'}}>
            <button onClick={()=>setWeekIdx(i=>Math.max(0,i-1))} disabled={weekIdx===0}
              style={{padding:'5px 12px',borderRadius:7,border:'1px solid #ddd',background:'#fff',cursor:weekIdx===0?'default':'pointer',fontSize:13,color:weekIdx===0?'#ccc':'#333'}}>←</button>
            <div style={{fontSize:13,fontWeight:500,minWidth:155,textAlign:'center'}}>
              {weekMonthLabel}<br/><span style={{fontSize:11,color:'#888',fontWeight:400}}>{currentWeek?.label}</span>
            </div>
            <button onClick={()=>setWeekIdx(i=>Math.min(allWeeks.length-1,i+1))} disabled={weekIdx===allWeeks.length-1}
              style={{padding:'5px 12px',borderRadius:7,border:'1px solid #ddd',background:'#fff',cursor:weekIdx===allWeeks.length-1?'default':'pointer',fontSize:13,color:weekIdx===allWeeks.length-1?'#ccc':'#333'}}>→</button>
            <div style={{flex:1}}/>
            <select value={filterInstructor} onChange={e=>setFilterInstructor(e.target.value)}
              style={{padding:'5px 10px',borderRadius:7,border:'1px solid #ddd',fontSize:12,background:'#fff'}}>
              <option value="">All instructors</option>
              {ALL_INSTRUCTORS.map(n=><option key={n} value={n}>{n}</option>)}
            </select>
            <select value={filterSlot} onChange={e=>setFilterSlot(e.target.value)}
              style={{padding:'5px 10px',borderRadius:7,border:'1px solid #ddd',fontSize:12,background:'#fff'}}>
              <option value="">Both slots</option>
              <option value="d">Day only</option>
              <option value="e">Evening only</option>
            </select>
          </div>

          <CourseLegend/>

          <div style={{display:'grid',gridTemplateColumns:'repeat(5,1fr)',gap:6}}>
            {DAYS.map((day,i)=>{
              const dateStr=weekDates[i];
              const dayData=dateStr?schedData[dateStr]:null;
              const visibleAs=(dayData?.as||[]).filter(a=>cohortInfo[a.c]);
              const teachingSet=new Set(visibleAs.flatMap(a=>[...(a.i||[]),...(a.sb||[])]));
              const free=(dayData?.av||[]).filter(n=>!teachingSet.has(n));
              const shownAs=visibleAs.filter(a=>{
                if(filterInstructor&&![...(a.i||[]),...(a.sb||[])].includes(filterInstructor)) return false;
                if(filterSlot&&a.s!==filterSlot) return false;
                return true;
              });
              const dimmed=filterInstructor&&dayData&&!dayData.av?.includes(filterInstructor)&&!teachingSet.has(filterInstructor);
              return (
                <div key={day}>
                  <div style={{fontSize:12,fontWeight:600,color:'#374151',textAlign:'center',marginBottom:5}}>{day.slice(0,3)}</div>
                  <div onClick={()=>dateStr&&dayData&&setSelectedDay(dateStr)}
                    style={{borderRadius:8,border:'1px solid #e5e7eb',background:'#fff',padding:'8px',
                      cursor:dayData?'pointer':'default',opacity:dimmed?0.25:1,
                      transition:'box-shadow .12s',boxShadow:'0 1px 2px rgba(0,0,0,0.04)'}}
                    onMouseEnter={e=>{if(dayData)e.currentTarget.style.boxShadow='0 3px 12px rgba(0,0,0,0.1)';}}
                    onMouseLeave={e=>{e.currentTarget.style.boxShadow='0 1px 2px rgba(0,0,0,0.04)';}}>
                    {!dayData?(
                      <div style={{color:'#e5e7eb',fontSize:12,textAlign:'center',padding:'22px 0'}}>—</div>
                    ):(
                      <>
                        <div style={{fontSize:10,color:'#9ca3af',marginBottom:5}}>{fmt(dateStr)}</div>
                        <div style={{display:'flex',flexDirection:'column',gap:3,marginBottom:5}}>
                          {shownAs.map((a,idx)=>{
                            const color=getCourseColor(a.c,dateStr);
                            const wkInfo=getWkDay(a.c,dateStr);
                            const names=(a.i||[]);
                            const hasSub=(a.sb||[]).length>0;
                            return (
                              <div key={idx} style={{borderRadius:5,padding:'4px 7px',
                                background:color+'14',borderLeft:'2px solid '+color}}>
                                <div style={{display:'flex',justifyContent:'space-between',alignItems:'center',gap:4}}>
                                  <span style={{fontSize:10,fontWeight:700,color}}>{a.c}</span>
                                  <span style={{fontSize:9,color:'#9ca3af',whiteSpace:'nowrap'}}>
                                    {wkInfo?`W${wkInfo.w}D${wkInfo.d}`:''}
                                  </span>
                                </div>
                                <div style={{fontSize:10,color:'#374151',marginTop:1,lineHeight:1.3}}>
                                  <span style={{fontWeight:500,color:'#6b7280'}}>{a.m}</span>
                                  {names.length>0&&<span style={{marginLeft:4}}>{names.join(', ')}</span>}
                                  {hasSub&&<span style={{color:'#7c3aed'}}> +sub</span>}
                                </div>
                              </div>
                            );
                          })}
                        </div>
                        {free.length>0&&(
                          <div style={{borderTop:'1px solid #f5f5f5',paddingTop:4}}>
                            <div style={{fontSize:9,color:'#9ca3af',marginBottom:1}}>Free:</div>
                            <div style={{fontSize:10,color:'#15803d',fontWeight:500,lineHeight:1.5}}>{free.join(', ')}</div>
                          </div>
                        )}
                      </>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
          <div style={{fontSize:11,color:'#d1d5db',marginTop:6}}>Click any day for full detail and to edit assignments</div>
        </>
      )}

      {/* ── TEAM OVERVIEW ── */}
      {tab==='team'&&(
        <>
          <NavBar/>
          <div style={{display:'flex',flexDirection:'column',gap:6}}>
            {ALL_INSTRUCTORS.map(name=>{
              const weekSummary=weekDates.map((dateStr,i)=>{
                const dayData=dateStr?schedData[dateStr]:null;
                if(!dayData) return {dateStr,status:'off',teaching:[],subbing:[]};
                const onDuty=dayData.av?.includes(name);
                const teaching=dayData.as.filter(a=>cohortInfo[a.c]&&(a.i||[]).includes(name));
                const subbing=dayData.as.filter(a=>cohortInfo[a.c]&&(a.sb||[]).includes(name));
                return {dateStr,day:DAYS[i].slice(0,3),
                  status:!onDuty?'off':(teaching.length||subbing.length)?'busy':'free',
                  teaching,subbing};
              });
              const busyDays=weekSummary.filter(d=>d.status==='busy').length;
              const freeDays=weekSummary.filter(d=>d.status==='free').length;
              const offDays=weekSummary.filter(d=>d.status==='off').length;
              return (
                <div key={name} style={{border:'1px solid #f0f0f0',borderRadius:10,
                  padding:'10px 14px',background:'#fff',display:'flex',alignItems:'center',gap:10,flexWrap:'wrap'}}>
                  <div style={{fontWeight:600,fontSize:13,minWidth:70}}>{name}</div>
                  <div style={{display:'flex',gap:3,flex:1,minWidth:260}}>
                    {weekSummary.map((d,i)=>{
                      let bg,border,textColor,label;
                      if(d.status==='off'){bg='#f9fafb';border='#f0f0f0';textColor='#d1d5db';label='Off';}
                      else if(d.status==='free'){bg='#f0fdf4';border='#86efac';textColor='#15803d';label='Free';}
                      else {
                        const all=[...d.teaching,...d.subbing];
                        const color=all.length===1?getCourseColor(all[0].c,d.dateStr):'#374151';
                        bg=all.length===1?color+'18':'#f3f4f6';
                        border=all.length===1?color+'55':'#e5e7eb';
                        textColor=all.length===1?color:'#374151';
                        label=all.map(a=>a.c+(d.subbing.includes(a)?'*':'')).join(', ');
                      }
                      return (
                        <div key={i} title={d.status==='busy'?[...d.teaching,...d.subbing]
                          .map(a=>cohortLabel(a.c)+' · '+COURSES[a.m]).join(' | '):''}
                          style={{flex:1,minWidth:0,borderRadius:6,border:'1px solid '+border,
                            background:bg,padding:'5px 4px',textAlign:'center'}}>
                          <div style={{fontSize:9,color:'#9ca3af',marginBottom:2}}>{d.day}</div>
                          <div style={{fontSize:10,fontWeight:600,color:textColor,
                            overflow:'hidden',textOverflow:'ellipsis',whiteSpace:'nowrap'}}>{label}</div>
                        </div>
                      );
                    })}
                  </div>
                  <div style={{display:'flex',gap:8,fontSize:11,color:'#9ca3af',whiteSpace:'nowrap'}}>
                    {busyDays>0&&<span style={{color:'#374151',fontWeight:500}}>{busyDays} teaching</span>}
                    {freeDays>0&&<span style={{color:'#15803d',fontWeight:500}}>{freeDays} free</span>}
                    {offDays>0&&<span>{offDays} off</span>}
                  </div>
                </div>
              );
            })}
          </div>
        </>
      )}

      {/* ── COHORTS ── */}
      {tab==='cohorts'&&(
        <div>
          <div style={{fontSize:12,color:'#888',marginBottom:14}}>Click any cohort to see their full course schedule.</div>
          <div style={{display:'grid',gridTemplateColumns:'repeat(auto-fill,minmax(185px,1fr))',gap:10}}>
            {Object.entries(cohortInfo).map(([id,info])=>{
              const dayCount=Object.values(schedData).filter(d=>d.as.some(a=>a.c===id)).length;
              let currentMod=null;
              for(const dateStr of weekDates){
                const d=schedData[dateStr];
                if(d){const a=d.as.find(x=>x.c===id&&cohortInfo[x.c]);if(a){currentMod=a.m;break;}}
              }
              const color=currentMod?COURSE_COLORS[currentMod]||'#888':'#9ca3af';
              return (
                <div key={id} onClick={()=>setSelectedCohort(id)}
                  style={{background:'#fff',border:'1px solid '+color+'33',borderTop:'3px solid '+color,
                    borderRadius:10,padding:'13px 15px',cursor:'pointer',transition:'box-shadow .12s'}}
                  onMouseEnter={e=>e.currentTarget.style.boxShadow='0 4px 14px rgba(0,0,0,0.1)'}
                  onMouseLeave={e=>e.currentTarget.style.boxShadow='none'}>
                  <div style={{fontSize:15,fontWeight:700,color:'#1a1a2e',marginBottom:2}}>Cohort {id}</div>
                  <div style={{fontSize:11,color:'#888',marginBottom:5}}>{info.slot==='d'?'Day':'Evening'} · {fmt(info.start)} – {fmt(info.end)}</div>
                  {currentMod&&(
                    <div style={{fontSize:11,background:color+'12',color,borderRadius:4,
                      padding:'2px 6px',display:'inline-block',marginBottom:5,fontWeight:500}}>
                      Now: {currentMod} · {COURSES[currentMod]?.split(' ').slice(0,2).join(' ')||''}
                    </div>
                  )}
                  <div style={{fontSize:11,color:'#9ca3af'}}>{dayCount} class days · View →</div>
                </div>
              );
            })}
          </div>
        </div>
      )}

      {selectedDay&&!editTarget&&<DayModal dateStr={selectedDay} data={schedData} cohortInfo={cohortInfo} onEdit={handleOpenEdit} onClose={()=>setSelectedDay(null)}/>}
      {editTarget&&<EditModal dateStr={editTarget.dateStr} assignmentIdx={editTarget.assignmentIdx} data={schedData} onSave={handleSaveEdit} onClose={()=>{setEditTarget(null);setSelectedDay(editTarget.dateStr);}}/>}
      {selectedCohort&&<CohortDetail cohortId={selectedCohort} data={schedData} onClose={()=>setSelectedCohort(null)}/>}
      {showCohortManager&&<CohortManagerModal cohortInfo={cohortInfo} schedData={schedData}
        onUpdate={info=>{setCohortInfo(info);setShowCohortManager(false);}}
        onDelete={handleDeleteCohort}
        onClose={()=>setShowCohortManager(false)}/>}
    </div>
  );
}
